import { getProfile, getFaq, getTools } from '@/sanity/lib'
import Image from 'next/image'
import { urlFor } from '@/sanity/lib/image'
import { PortableText } from '@portabletext/react'
import { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from '@/components/ui/Accordion'
import { Github, Linkedin, Mail, Twitter, Instagram, Youtube, ExternalLink } from 'lucide-react'
import type { Metadata } from 'next'

export const metadata: Metadata = {
    title: 'About | Langley',
    description: 'Motion Graphics Editor, AMV/PMV Creator, and Developer.',
}

export const revalidate = 60

export default async function AboutPage() {
    const [profile, faq, tools] = await Promise.all([
        getProfile(),
        getFaq(),
        getTools()
    ])

    // Fallback values if Sanity data is empty
    const displayName = profile?.name || "Langley"
    const displayRole = profile?.role || "Video Editor yang kebetulan jago ngoding"
    const displayBio = profile?.longBio || []
    const displaySocials = profile?.socials || []

    return (
        <div className="min-h-screen pt-32 pb-20">
            <div className="container max-w-5xl space-y-24">

                {/* Profile Intro */}
                <section className="grid grid-cols-1 md:grid-cols-12 gap-12 items-center">
                    <div className="md:col-span-5 flex justify-center md:justify-start">
                        <div className="relative w-72 h-72 md:w-96 md:h-96 rounded-3xl overflow-hidden border border-white/10 shadow-2xl group">
                            {profile?.avatarImage ? (
                                <Image
                                    src={urlFor(profile.avatarImage).width(600).height(600).url()}
                                    alt={displayName}
                                    fill
                                    className="object-cover transition-transform duration-700 group-hover:scale-105"
                                />
                            ) : (
                                <div className="w-full h-full bg-gradient-to-br from-primary/10 to-accent/10 flex items-center justify-center">
                                    <span className="font-black text-8xl text-white/10">L.</span>
                                </div>
                            )}
                            {/* Glow */}
                            <div className="absolute -inset-1 bg-gradient-to-br from-primary/20 to-accent/20 rounded-3xl blur-2xl -z-10 opacity-60" />
                        </div>
                    </div>

                    <div className="md:col-span-7 space-y-6">
                        <div className="space-y-2">
                            <span className="text-xs font-mono tracking-widest text-primary uppercase">About Me</span>
                            <h1 className="text-4xl md:text-5xl font-black tracking-tight">
                                {displayName}
                            </h1>
                            <p className="text-xl text-muted-foreground font-medium">
                                {displayRole}
                            </p>
                        </div>

                        <div className="prose prose-lg dark:prose-invert text-muted-foreground leading-relaxed max-w-none">
                            {displayBio.length > 0 ? (
                                <PortableText value={displayBio} />
                            ) : (
                                <p>
                                    I craft motion graphics and edit videos with a focus on rhythm, pacing, and visual impact.
                                    Specializing in AMV, PMV, and commercial mograph projects.
                                </p>
                            )}
                        </div>

                        {/* Social Links */}
                        <div className="flex gap-3 pt-2">
                            {displaySocials.map((social) => (
                                <a
                                    key={social.platform}
                                    href={social.url}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="p-3 rounded-full glass-heavy hover:bg-primary hover:text-white transition-all hover:scale-110"
                                    aria-label={social.platform}
                                >
                                    {social.platform.toLowerCase().includes('github') && <Github className="w-5 h-5" />}
                                    {social.platform.toLowerCase().includes('linkedin') && <Linkedin className="w-5 h-5" />}
                                    {social.platform.toLowerCase().includes('twitter') && <Twitter className="w-5 h-5" />}
                                    {social.platform.toLowerCase().includes('mail') && <Mail className="w-5 h-5" />}
                                    {social.platform.toLowerCase().includes('instagram') && <Instagram className="w-5 h-5" />}
                                    {social.platform.toLowerCase().includes('youtube') && <Youtube className="w-5 h-5" />}
                                </a>
                            ))}
                        </div>
                    </div>
                </section>

                {/* Tools / Tech Stack */}
                {tools && tools.length > 0 && (
                    <section className="space-y-8">
                        <div className="flex items-center gap-4">
                            <h2 className="text-2xl font-bold">My Toolbox</h2>
                            <div className="h-px flex-1 bg-border" />
                        </div>

                        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-4">
                            {tools.map((tool) => (
                                <a
                                    key={tool._id}
                                    href={tool.url || '#'}
                                    target={tool.url ? '_blank' : undefined}
                                    rel="noopener noreferrer"
                                    className="group flex flex-col items-center justify-center p-6 rounded-2xl glass-card hover:border-primary/50 transition-all"
                                >
                                    <div className="relative w-12 h-12 mb-3 flex items-center justify-center">
                                        {tool.icon ? (
                                            <Image
                                                src={urlFor(tool.icon).width(96).height(96).url()}
                                                alt={tool.name}
                                                width={48}
                                                height={48}
                                                className="object-contain grayscale group-hover:grayscale-0 transition-all"
                                            />
                                        ) : (
                                            <div className="w-full h-full rounded-xl bg-secondary flex items-center justify-center">
                                                <span className="text-lg font-bold opacity-50">{tool.name[0]}</span>
                                            </div>
                                        )}
                                    </div>
                                    <span className="text-sm font-medium text-center">{tool.name}</span>
                                    {tool.url && (
                                        <ExternalLink className="w-3 h-3 mt-1 opacity-0 group-hover:opacity-50 transition-opacity" />
                                    )}
                                </a>
                            ))}
                        </div>
                    </section>
                )}

                {/* FAQ */}
                {faq?.items && faq.items.length > 0 && (
                    <section className="space-y-8 max-w-3xl mx-auto pt-12 border-t border-border">
                        <h2 className="text-2xl font-bold text-center">Frequently Asked Questions</h2>
                        <Accordion className="space-y-4">
                            {faq.items.map((item, i) => (
                                <AccordionItem key={i} value={`item-${i}`}>
                                    <AccordionTrigger>{item.question}</AccordionTrigger>
                                    <AccordionContent>
                                        <PortableText value={item.answer} />
                                    </AccordionContent>
                                </AccordionItem>
                            ))}
                        </Accordion>
                    </section>
                )}

            </div>
        </div>
    )
}
